package server

// alpha.20 BYTE-IDENTITY GATE for the single-buffer ordered-JSON serializer.
//
// The committed golden file `testdata/a20-ordered-json-golden.jsonl` was generated by the PRE-CHANGE code
// (`go test -run TestA20GenerateGolden` on commit 7d1178e, before the marshal rewrite) and frozen: each line
// carries the raw input document (base64), the exact bytes `marshalOrderedNodeJSON` produced for it, and for
// string cases the raw Go string plus the exact bytes `marshalNodeJSONString` produced. The new serializer must
// reproduce every byte, so a difference means the patch is wrong, not the golden.
//
// The corpus deliberately exercises the shapes where a rewrite goes wrong: member order (integer-like keys
// re-ordered the way JavaScript does, then insertion order), nested objects/arrays, every control character,
// quote/backslash, U+2028/U+2029, astral emoji, invalid UTF-8 bytes (each replaced with U+FFFD), lone and paired
// UTF-16 surrogates, -0/1e21/1e-7/big integers, top-level scalars, and 4 levels of nesting.
//
// A WRONG HINT MUST NOT CHANGE CONTENT. Every document is marshalled with hints 0, 1, len+7 and 1<<20; all four
// must equal the frozen output, because the hint pre-sizes the buffer and nothing else. The test refuses to pass
// vacuously: fewer than 20 records is a failure.

import (
	"bufio"
	"bytes"
	"encoding/base64"
	"encoding/json"
	"os"
	"path/filepath"
	"testing"
)

type a20GoldenCase struct {
	Name     string `json:"name"`
	Kind     string `json:"kind"`
	InputB64 string `json:"inputB64"`
	TextB64  string `json:"textB64"`
	Output   string `json:"outputB64"`
}

func readA20Golden(t *testing.T) []a20GoldenCase {
	t.Helper()
	path := filepath.Join("testdata", "a20-ordered-json-golden.jsonl")
	file, err := os.Open(path)
	if err != nil {
		t.Fatalf("open the frozen golden set %s: %v", path, err)
	}
	defer file.Close()
	var cases []a20GoldenCase
	scanner := bufio.NewScanner(file)
	scanner.Buffer(make([]byte, 64*1024), 4*1024*1024)
	for scanner.Scan() {
		line := bytes.TrimSpace(scanner.Bytes())
		if len(line) == 0 {
			continue
		}
		var record a20GoldenCase
		if err := json.Unmarshal(line, &record); err != nil {
			t.Fatalf("decode golden record: %v", err)
		}
		cases = append(cases, record)
	}
	if err := scanner.Err(); err != nil {
		t.Fatalf("read golden set: %v", err)
	}
	if len(cases) < 20 {
		t.Fatalf("the golden set holds %d records; at least 20 are required, or the test could pass vacuously", len(cases))
	}
	return cases
}

func TestA20OrderedJSONMarshalByteIdentity(t *testing.T) {
	cases := readA20Golden(t)
	documents, stringsSeen := 0, 0
	for _, testCase := range cases {
		expected, err := base64.StdEncoding.DecodeString(testCase.Output)
		if err != nil {
			t.Fatalf("%s: decode expected output: %v", testCase.Name, err)
		}
		switch testCase.Kind {
		case "document":
			raw, err := base64.StdEncoding.DecodeString(testCase.InputB64)
			if err != nil {
				t.Fatalf("%s: decode input: %v", testCase.Name, err)
			}
			parsed, err := decodeOrderedNodeJSON(raw)
			if err != nil {
				t.Fatalf("%s: decode input document: %v", testCase.Name, err)
			}
			if got, err := marshalOrderedNodeJSON(parsed); err != nil || !bytes.Equal(got, expected) {
				t.Fatalf("%s: marshalOrderedNodeJSON = %q (err %v), frozen pre-change bytes = %q", testCase.Name, got, err, expected)
			}
			for _, hint := range []int{0, 1, len(expected) + 7, 1 << 20} {
				got, err := marshalOrderedNodeJSONHint(parsed, hint)
				if err != nil || !bytes.Equal(got, expected) {
					t.Fatalf("%s: marshalOrderedNodeJSONHint(hint=%d) = %q (err %v), frozen bytes = %q; a hint may only pre-size the buffer", testCase.Name, hint, got, err, expected)
				}
			}
			// The hint path and the plain path must agree with each other as well as with the golden: a hint that
			// changed content would have to change both to hide here.
			plain, _ := marshalOrderedNodeJSON(parsed)
			hinted, _ := marshalOrderedNodeJSONHint(parsed, 1<<20)
			if !bytes.Equal(plain, hinted) {
				t.Fatalf("%s: the hinted and unhinted serializers disagree (%d vs %d bytes)", testCase.Name, len(plain), len(hinted))
			}
			documents++
		case "string":
			raw, err := base64.StdEncoding.DecodeString(testCase.TextB64)
			if err != nil {
				t.Fatalf("%s: decode input string: %v", testCase.Name, err)
			}
			text := string(raw)
			if got := appendCharacterJSONString(nil, text); !bytes.Equal(got, expected) {
				t.Fatalf("%s: appendCharacterJSONString = %q, frozen pre-change writeCharacterJSONString bytes = %q", testCase.Name, got, expected)
			}
			if got, err := marshalNodeJSONString(text); err != nil || !bytes.Equal(got, expected) {
				t.Fatalf("%s: marshalNodeJSONString = %q (err %v), frozen bytes = %q", testCase.Name, got, err, expected)
			}
			// Cross-check against the ORIGINAL writer, which this change did not touch: the two encoders must not
			// drift apart, and the reference is the pre-existing pinned implementation rather than the new one.
			var reference bytes.Buffer
			writeCharacterJSONString(&reference, text)
			if !bytes.Equal(reference.Bytes(), expected) {
				t.Fatalf("%s: writeCharacterJSONString = %q, frozen bytes = %q", testCase.Name, reference.Bytes(), expected)
			}
			stringsSeen++
		default:
			t.Fatalf("%s: unknown golden kind %q", testCase.Name, testCase.Kind)
		}
	}
	if documents == 0 || stringsSeen == 0 {
		t.Fatalf("the golden set exercised %d documents and %d strings; both kinds are required", documents, stringsSeen)
	}
	t.Logf("byte identity: %d documents (4 hints each) + %d strings match the frozen pre-change golden", documents, stringsSeen)
}
